import re

def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""

    if not text:
        raise ValueError("Empty input")

    text = text.strip()

    # Check for negative sign
    if text.startswith('-'):
        raise ValueError("Negative durations not allowed")

    # Try bare integer first (seconds)
    if text.isdigit():
        return int(text)

    # Try ISO 8601 format (PT...)
    if text.startswith('P'):
        return parse_iso8601(text)

    # Try clock notation (hh:mm:ss or mm:ss)
    if ':' in text:
        return parse_clock_notation(text)

    # Try number+unit components format
    return parse_components(text)


def parse_iso8601(text: str) -> int:
    """Parse ISO 8601 duration format like PT1H30M or P1DT2H."""
    if not text.startswith('P'):
        raise ValueError("Invalid ISO 8601 format")

    # Remove the P prefix
    text = text[1:]

    # Split on T if present
    date_part = ""
    time_part = ""

    if 'T' in text:
        parts = text.split('T')
        if len(parts) != 2:
            raise ValueError("Invalid ISO 8601 format")
        date_part, time_part = parts
    else:
        date_part = text

    total_seconds = 0.0

    # Parse date part (W, D)
    if date_part:
        weeks = re.findall(r'(\d+(?:\.\d+)?)W', date_part)
        days = re.findall(r'(\d+(?:\.\d+)?)D', date_part)

        for week in weeks:
            total_seconds += float(week) * 7 * 24 * 3600
        for day in days:
            total_seconds += float(day) * 24 * 3600

    # Parse time part (H, M, S)
    if time_part:
        hours = re.findall(r'(\d+(?:\.\d+)?)H', time_part)
        minutes = re.findall(r'(\d+(?:\.\d+)?)M', time_part)
        seconds = re.findall(r'(\d+(?:\.\d+)?)S', time_part)

        for hour in hours:
            total_seconds += float(hour) * 3600
        for minute in minutes:
            total_seconds += float(minute) * 60
        for second in seconds:
            total_seconds += float(second)

    if total_seconds == 0 and not date_part and not time_part:
        raise ValueError("Invalid ISO 8601 format")

    return round(total_seconds)


def parse_clock_notation(text: str) -> int:
    """Parse clock notation like hh:mm:ss or mm:ss."""
    parts = text.split(':')

    if len(parts) == 2:
        # mm:ss format
        try:
            minutes = int(parts[0])
            seconds = int(parts[1])
            if minutes < 0 or seconds < 0:
                raise ValueError("Negative durations not allowed")
            return minutes * 60 + seconds
        except ValueError as e:
            if "Negative" in str(e):
                raise
            raise ValueError("Invalid clock notation")
    elif len(parts) == 3:
        # hh:mm:ss format
        try:
            hours = int(parts[0])
            minutes = int(parts[1])
            seconds = int(parts[2])
            if hours < 0 or minutes < 0 or seconds < 0:
                raise ValueError("Negative durations not allowed")
            return hours * 3600 + minutes * 60 + seconds
        except ValueError as e:
            if "Negative" in str(e):
                raise
            raise ValueError("Invalid clock notation")
    else:
        raise ValueError("Invalid clock notation")


