    pattern = r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)'

    matches = re.findall(pattern, text)

    if not matches:
        raise ValueError("No valid number+unit components found")

    # Check that we matched the entire input (accounting for spaces)
